// Mechanical attribute update: preserve hrefs, prose and internal navigation.
function newTabLinks(html){return html.replace(/<a\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi,tag=>{const href=tag.match(/\bhref\s*=\s*(?:"([^"]*)"|'([^']*)')/i);if(!href)return tag;const raw=href[1]??href[2];if(!/^https?:\/\/|^\/\//i.test(raw))return tag;let url;try{url=new URL(raw.replace(/&amp;/g,'&'),'https://jiayuchen-math.github.io')}catch{return tag}if(url.hostname==='jiayuchen-math.github.io')return tag;const rel=tag.match(/\brel\s*=\s*(?:"([^"]*)"|'([^']*)')/i);const values=new Set((rel?(rel[1]??rel[2]):'').split(/\s+/).filter(Boolean));values.add('noopener');values.add('noreferrer');return tag.replace(/\s+(?:target|rel)\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi,'').replace(/\s*>$/,' target="_blank" rel="'+E([...values].join(' '))+'">')})}
function walk(dir){for(const entry of fs.readdirSync(path.join(root,dir),{withFileTypes:true})){if(['.git','node_modules'].includes(entry.name))continue;const file=path.join(dir,entry.name);if(entry.isDirectory())walk(file);else if(entry.name.endsWith('.html')){const before=read(file);let after=newTabLinks(before);if(file.replaceAll('\\','/').startsWith('notes/reading-notes/library'))after=after.replace('curated free full-text mathematics books and notes','curated mathematics books and notes with access information');if(file.replaceAll('\\','/').startsWith('notes/reading-notes/library')&&!after.includes('/* access badges */'))after=after.replace('</style>','/* access badges */.badge{display:inline-block;border:1px solid var(--line);border-radius:4px;padding:2px 7px;font-size:13px;line-height:1.6}</style>');if(after!==before)save(file,after)}}}walk('');
// Keep repeated general caveats on the single disclaimer page, not every card.
function editPageCopy(dir){for(const entry of fs.readdirSync(path.join(root,dir),{withFileTypes:true})){
 if(['.git','node_modules'].includes(entry.name))continue;
 const file=path.join(dir,entry.name),name=file.replaceAll('\\','/');
 if(entry.isDirectory()){if(name!=='resources/data')editPageCopy(file)}
 else if(entry.name.endsWith('.html')){const before=read(file),after=cleanPageCopy(before,name);if(after!==before)save(file,after)}
}}
